/**
 * NavMeshFinder - Pathfinding on navigation mesh
 *
 * Two-phase pathfinding on polygon-based navigation mesh:
 * 1. A* on polygon graph to find corridor of polygons
 * 2. Simple Stupid Funnel Algorithm to compute smooth path through portals
 *
 * Features:
 * - Binary heap priority queue for O(log n) A* operations
 * - Euclidean heuristic between polygon centroids
 * - Path caching with configurable TTL
 * - Node pooling to avoid allocations
 *
 * **Usage**
 *
 * ```js
 * const finder = new NavMeshFinder(navMesh);
 * const path = finder.findPath(startPos, goalPos);
 * if (path) {
 *   // path is array of { x, y, z } waypoints
 * }
 * ```
 *
 * @class NavMeshFinder
 * @short Pathfinding on navigation mesh
 * @category Navigation
 * @tags NavMesh, A*, Funnel, Pathfinding
 */
export class NavMeshFinder {
    /**
     * Create a new navmesh pathfinder.
     *
     * @param {NavMesh} navMesh - Navigation mesh to search.
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.maxIterations=500] - Maximum A* iterations.
     * @param {number} [config.cacheTimeout=5000] - Path cache TTL in ms.
     */
    constructor(navMesh: NavMesh, config?: {
        maxIterations?: number;
        cacheTimeout?: number;
    });
    navMesh: NavMesh;
    maxIterations: number;
    cacheTimeout: number;
    _openHeap: BinaryHeap;
    _openSet: Map<any, any>;
    _closedSet: Map<any, any>;
    _nodePool: any[];
    _nodePoolIndex: number;
    _corridorCache: Map<any, any>;
    _maxCacheSize: number;
    /**
     * Three.js-style type flag.
     * @type {boolean}
     */
    isNavMeshFinder: boolean;
    /**
     * Configure pathfinder parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {NavMeshFinder} This instance for chaining.
     */
    set(config: any): NavMeshFinder;
    /**
     * Find path from start to goal world positions.
     *
     * @param {THREE.Vector3} start - Start world position.
     * @param {THREE.Vector3} goal - Goal world position.
     * @param {Object} [options] - Search options.
     * @returns {Array<{x: number, y: number, z: number}>|null} Path waypoints or null.
     */
    findPath(start: THREE.Vector3, goal: THREE.Vector3, options?: any): Array<{
        x: number;
        y: number;
        z: number;
    }> | null;
    /**
     * A* search on polygon graph.
     * Returns corridor (sequence of polygons from start to goal).
     *
     * @param {NavMeshPolygon} startPoly - Start polygon.
     * @param {NavMeshPolygon} goalPoly - Goal polygon.
     * @returns {Array<{polygon: NavMeshPolygon, portal: Object}>|null} Corridor or null.
     * @private
     */
    private _findCorridor;
    /**
     * Reconstruct corridor from goal node.
     *
     * @param {Object} goalNode - Goal node with parent chain.
     * @returns {Array<{polygon: NavMeshPolygon, portal: Object}>} Corridor.
     * @private
     */
    private _reconstructCorridor;
    /**
     * Simple Stupid Funnel Algorithm.
     * Converts polygon corridor to smooth path through portals.
     *
     * Reference: "Simple Stupid Funnel Algorithm" by Mikko Mononen
     *
     * @param {Array<{polygon: NavMeshPolygon, portal: Object}>} corridor - Polygon corridor.
     * @param {THREE.Vector3} start - Start position.
     * @param {THREE.Vector3} goal - Goal position.
     * @returns {Array<{x: number, y: number, z: number}>} Smooth path.
     * @private
     */
    private _funnelPath;
    /**
     * Extract portals from corridor for funnel algorithm.
     *
     * @param {Array<{polygon: NavMeshPolygon, portal: Object}>} corridor - Polygon corridor.
     * @param {THREE.Vector3} start - Start position.
     * @param {THREE.Vector3} goal - Goal position.
     * @returns {Array<{left: Object, right: Object}>} Portal list.
     * @private
     */
    private _extractPortals;
    /**
     * Signed 2D triangle area (for funnel algorithm).
     * Positive if C is to the left of AB, negative if to the right.
     *
     * @param {THREE.Vector3} a - First vertex.
     * @param {THREE.Vector3} b - Second vertex.
     * @param {THREE.Vector3} c - Third vertex.
     * @returns {number} Signed area.
     * @private
     */
    private _triArea2D;
    /**
     * Euclidean heuristic between polygon centroids.
     *
     * @param {NavMeshPolygon} polyA - First polygon.
     * @param {NavMeshPolygon} polyB - Second polygon.
     * @returns {number} Heuristic distance.
     * @private
     */
    private _heuristic;
    /**
     * Euclidean distance between two points.
     *
     * @param {Object} a - First point.
     * @param {Object} b - Second point.
     * @returns {number} Distance.
     * @private
     */
    private _distance;
    /**
     * Get or create a node from the pool.
     *
     * @param {NavMeshPolygon} polygon - Polygon for the node.
     * @returns {Object} Node object.
     * @private
     */
    private _getNode;
    /**
     * Cache a corridor result.
     *
     * @param {string} key - Cache key.
     * @param {Array} corridor - Corridor to cache.
     * @private
     */
    private _cacheCorridor;
    /**
     * Invalidate all cached corridors.
     * Call when navigation mesh changes.
     */
    invalidateCache(): void;
    /**
     * Get cache statistics.
     *
     * @returns {Object} Cache info.
     */
    getCacheInfo(): any;
    /**
     * Get the ground height at a position on the navmesh.
     * Used for kinematic bodies to stay on the navmesh surface.
     *
     * @param {number} x - World X coordinate.
     * @param {number} z - World Z coordinate.
     * @returns {number|null} Ground height or null if not on navmesh.
     */
    getHeightAt(x: number, z: number): number | null;
}
import { BinaryHeap } from './BinaryHeap.js';
